import type {FC, ReactNode} from 'react';
import React from 'react';

import {ChevronDown} from '@gravity-ui/icons';
import type {DisclosureProps} from '@gravity-ui/uikit';
import {Disclosure, Icon} from '@gravity-ui/uikit';

import {cnTrackerDisclosure} from './TrackerDisclosure.classname';

import './TrackerDisclosure.scss';

export type TrackerDisclosureProps = DisclosureProps & {
    summaryClassName?: string;
    toggleClassName?: string;
    arrowClassName?: string;
    arrowSize?: number;
    toolbar?: ReactNode;
};

export const TrackerDisclosure: FC<TrackerDisclosureProps> = ({
    children,
    summary,
    arrowPosition = 'end',
    arrowSize = 20,
    className,
    summaryClassName,
    toggleClassName,
    arrowClassName,
    toolbar,
    ...props
}) => {
    return (
        <Disclosure className={cnTrackerDisclosure(null, className)} {...props}>
            <Disclosure.Summary>
                {(props) => {
                    const {ariaControls, expanded, ...restProps} = props;

                    const collapseIcon = (
                        <Icon
                            className={cnTrackerDisclosure(
                                'collapse-icon',
                                {
                                    expanded: expanded,
                                },
                                arrowClassName,
                            )}
                            data={ChevronDown}
                            width={arrowSize}
                            height={arrowSize}
                        />
                    );

                    return (
                        <div
                            className={cnTrackerDisclosure(
                                'summary',
                                {expanded: expanded},
                                summaryClassName,
                            )}
                        >
                            <button
                                type="button"
                                className={cnTrackerDisclosure('toggle', toggleClassName)}
                                aria-controls={ariaControls}
                                aria-expanded={expanded}
                                {...restProps}
                            >
                                {arrowPosition === 'start' && collapseIcon}
                                {summary}
                                {arrowPosition === 'end' && collapseIcon}
                            </button>
                            {toolbar}
                        </div>
                    );
                }}
            </Disclosure.Summary>
            {children}
        </Disclosure>
    );
};
